import * as T from '../vendor/three.module.js';
import {ITEMS,CHAPTERS,questStage,LOCATIONS,ACTION_LABELS,DEFAULT_SETTINGS,heightAt} from './data.js';
import {blueprintCost} from './core.js';
import {keyName} from './input.js';
import {renderSettings} from './options.js';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const LOGO='<svg viewBox="0 0 80 90" fill="none" stroke="currentColor" stroke-width="1.7"><path d="M13 66V36a27 27 0 0 1 54 0v30M23 64V36a17 17 0 0 1 34 0v28M6 72h68M19 80h42M40 2v18M5 40h15M60 40h15"/><path d="m40 30 10 16-10 17-10-17Z"/><circle cx="40" cy="46" r="3" fill="currentColor"/></svg>';
export class UI{
 constructor(game){this.g=game;this.overlay=document.querySelector('#overlay');this.hud=document.querySelector('#hud');this.toasts=document.querySelector('#notifications');this.tab='journal';this.dialogue=null;this.overlay.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(b&&!b.disabled){game.audio.play('menu');this.action(b.dataset.action,b.dataset.value);}});this.overlay.addEventListener('input',e=>{const k=e.target.dataset.setting;if(k){game.settings[k]=e.target.type==='checkbox'?e.target.checked:e.target.type==='range'?Number(e.target.value):e.target.value;game.applySettings(k);if(k==='quality')this.openBook('settings');}});this.overlay.addEventListener('click',e=>{if(e.target.closest('.worldmap'))this.mapPin(e);});this.minimapTick=0;}
 focus(){queueMicrotask(()=>this.overlay.querySelector('button:not(:disabled)')?.focus());}
 bindingText(text){const keys={Q:'ability',E:'interact',R:'rotate',F:'detach',Z:'undo'};return text.replace(/\[(Q|E|R|F|Z)\]/g,(_,key)=>'['+this.g.input.label(keys[key])+']');}
 set(html,mode){this.g.mode=mode;this.g.input.enabled=false;this.g.input.unlock();this.overlay.innerHTML=html;if(!this.g.started)this.overlay.querySelector('[data-action="abilityWheel"]')?.remove();this.focus();}
 title(){this.hud.hidden=true;const save=this.g.saves.load();this.set(`<section class="title-screen"><div class="chapter-tag"><strong>CHAPTER I</strong>Where the sky fell</div><div class="title-art">${LOGO}</div><div class="eyebrow" style="margin-bottom:22px">Follow the broken line</div><h1>AETHERWILD</h1><p class="subtitle">THE BROKEN HORIZON</p><p class="title-copy">The engines fell silent.<br>The wild found its voice.<br>Some things are worth fixing differently.</p><div class="title-actions">${save?'<button class="primary" data-action="continue">Continue <span>↗</span></button>':''}<button class="${save?'secondary':'primary'}" data-action="new">New expedition <span>↗</span></button><button class="secondary" data-action="settings">Settings</button></div><div class="title-footer"><span>Mossglass Basin · Playable chapter · v0.3</span><span>Original world & music · Keyboard + mouse / gamepad</span></div></section>`,'title');}
 play(){this.overlay.innerHTML='';this.g.mode='play';this.g.input.clear();this.g.input.enabled=true;this.g.input.lock();this.g.audio.start();this.hud.hidden=false;if(!this.hud.innerHTML)this.makeHUD();}
 makeHUD(){this.hud.innerHTML=`<div class="vignette"></div><div class="vitals"><div><div class="player-name">IRI · EXPEDITION MECHANIC</div><div class="health"></div><div class="stamina"><i></i></div></div></div><div class="compass"><span>·</span><b id="heading">N</b><span>·</span></div><div class="quest-hud"><div class="eyebrow">THE BASIN THAT BREATHES</div><p></p><small></small></div><div class="ability-hud"><div class="loom-icon">${LOGO}</div><div><span>Wayfarer Loom</span><small id="ability-label"></small></div></div><div class="reticle"></div><div class="interaction"></div><div class="loom-help" hidden></div><div class="minimap-wrap"><div class="map-hint"><span id="map-key"></span> Field map<br><br>MO SSGLASS BASIN</div><canvas class="minimap" width="264" height="264"></canvas></div><div class="location-reveal"><div class="eyebrow" style="margin-bottom:13px">THE SURFACE MARCHES</div><h2></h2><p></p></div>`;}
 update(dt){
  if(!this.hud.innerHTML)return;const g=this.g,s=g.state.player,i=g.input;
  const health=this.hud.querySelector('.health');health.setAttribute('role','progressbar');health.setAttribute('aria-label','Health');health.setAttribute('aria-valuemin','0');health.setAttribute('aria-valuemax',String(s.maxHp));health.setAttribute('aria-valuenow',String(s.hp));
  this.hud.querySelector('.health').innerHTML=Array.from({length:s.maxHp},(_,n)=>`<span class="heart ${n>=s.hp?'empty':''}"></span>`).join('');this.hud.querySelector('.stamina i').style.width=100*s.stamina/s.maxStamina+'%';
  this.hud.querySelector('.quest-hud p').textContent=CHAPTERS[questStage(g.state)].objective;this.hud.querySelector('.quest-hud small').textContent=`${i.label('journal')} Journal  ·  ${i.label('pause')} Pause`;
  this.hud.querySelector('#ability-label').innerHTML=`<b class="key">${i.label('ability')}</b> ${g.loom?'Release Threadbind':g.rise.aiming?'Cancel Rise':g.activeAbility==='rise'?'Rise':'Threadbind'} · ${i.label('abilityWheel')} wheel${g.player.riding?' · '+i.label('jump')+' Dismount':''}`;
  this.hud.querySelector('#map-key').textContent='['+i.label('map')+']';
  const names=['N','NW','W','SW','S','SE','E','NE'];this.hud.querySelector('#heading').textContent=names[((Math.round(g.player.yaw/(Math.PI/4))%8)+8)%8];
  const help=this.hud.querySelector('.loom-help');help.hidden=!g.loom;help.innerHTML=`<strong>Threadbind · curated rigid joints</strong>${g.held?'Move to position · '+i.label('rotate')+' rotate · '+i.label('interact')+' place':'Look at a marked part · '+i.label('interact')+' lift'}<br>${i.label('detach')} detach · ${i.label('undo')} undo · ${i.label('ability')} leave`;
  const prompt=this.hud.querySelector('.interaction');prompt.innerHTML=g.prompt?`<div class="prompt"><b class="key">${esc(g.prompt.key||i.label('interact'))}</b>${esc(g.prompt.text)}</div>${g.prompt.sub?'<small>'+esc(g.prompt.sub)+'</small>':''}`:'';
  this.minimapTick+=dt;if(this.minimapTick>.15){this.minimapTick=0;this.drawMini();}
  if(!this.hud.querySelector('.enemy-markers'))this.hud.insertAdjacentHTML('beforeend','<div class="enemy-markers"></div>');
  const marks=[];for(const e of g.enemies){if(e.hp<=0||!e.alert||Math.hypot(e.x-g.player.pos.x,e.z-g.player.pos.z)>28)continue;const v=new T.Vector3(e.x,heightAt(e.x,e.z)+(e.kind==='sentinel'?3.1:2),e.z).project(g.camera);if(v.z>1||Math.abs(v.x)>1.1||Math.abs(v.y)>1.1)continue;marks.push(`<div class="enemy-marker ${e.phase==='tell'?'attacking':''}" style="left:${(v.x*.5+.5)*100}%;top:${(-v.y*.5+.5)*100}%"><span>${e.phase==='tell'?'! ':''}${e.kind==='sentinel'?'INTAKE SENTINEL':'MOSSBACK SCAVENGER'}</span><div role="progressbar" aria-label="Enemy health" aria-valuemin="0" aria-valuemax="${e.maxHp}" aria-valuenow="${e.hp}"><i style="width:${e.hp/e.maxHp*100}%"></i></div></div>`);}this.hud.querySelector('.enemy-markers').innerHTML=marks.join('');
  if(this.hud.querySelector('.map-hint'))this.hud.querySelector('.map-hint').innerHTML=`<span id="map-key">[${i.label('map')}]</span> Field map<br><br>MOSSGLASS BASIN`;
  this.hud.querySelector('.compass').style.display=g.settings.showCompass?'':'none';this.hud.querySelector('.minimap-wrap').style.display=g.settings.showMinimap?'':'none';this.hud.querySelector('.quest-hud').style.display=g.settings.guidance?'':'none';
 }
 drawMini(){const canvas=this.hud.querySelector('.minimap');if(!canvas)return;const ctx=canvas.getContext('2d'),p=this.g.player.pos;ctx.clearRect(0,0,264,264);ctx.fillStyle='#53745a';ctx.fillRect(0,0,264,264);ctx.save();ctx.translate(132,132);ctx.scale(1.7,1.7);ctx.translate(-p.x,-p.z);ctx.strokeStyle='#83b8a5';ctx.lineWidth=16;ctx.beginPath();for(let x=-200;x<210;x+=5){let z=42+Math.sin(x*.025)*4;x===-200?ctx.moveTo(x,z):ctx.lineTo(x,z);}ctx.stroke();ctx.fillStyle='#83b8a5';ctx.beginPath();ctx.ellipse(68,35,44,41,0,0,7);ctx.fill();ctx.strokeStyle='#b6b789';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(0,105);ctx.lineTo(-28,58);ctx.lineTo(-28,25);ctx.lineTo(-16,-20);ctx.lineTo(0,-103);ctx.stroke();for(const l of LOCATIONS)if(this.g.state.discovered.includes(l.id)){ctx.fillStyle=l.id==='reedwake'?'#f1d48d':'#d2d7aa';ctx.fillRect(l.x-2,l.z-2,4,4);}for(const pin of this.g.state.pins){ctx.strokeStyle='#efba83';ctx.strokeRect(pin.x-2,pin.z-2,4,4);}ctx.restore();ctx.save();ctx.translate(132,132);ctx.rotate(-this.g.player.yaw);ctx.fillStyle='#f6eac5';ctx.beginPath();ctx.moveTo(0,-11);ctx.lineTo(6,7);ctx.lineTo(0,4);ctx.lineTo(-6,7);ctx.fill();ctx.restore();ctx.fillStyle='#e1dfb9';ctx.font='15px sans-serif';ctx.fillText('N',127,22);}
 toast(text){const el=document.createElement('div');el.className='toast';el.textContent=text;this.toasts.append(el);setTimeout(()=>el.classList.add('out'),4300);setTimeout(()=>el.remove(),5000);}
 reveal(location){const el=this.hud.querySelector('.location-reveal');if(!el)return;el.querySelector('h2').textContent=location.name;el.querySelector('p').textContent=location.subtitle;el.classList.add('show');clearTimeout(this.revealTimer);this.revealTimer=setTimeout(()=>el.classList.remove('show'),4500);}
 talk(data,onComplete,choices=null){this.dialogue={title:data[0][0],subtitle:data[0][1],lines:data[1].map(text=>this.bindingText(text)),index:0,onComplete,choices};this.renderDialogue();}
 renderDialogue(){const d=this.dialogue;this.set(`<div class="modal-shade" style="background:#0e252249;backdrop-filter:none"><section class="dialogue" role="dialog" aria-modal="true" aria-label="${esc(d.title)}"><div class="eyebrow">${esc(d.subtitle)}</div><h2>${esc(d.title)}</h2><p>${esc(d.lines[d.index])}</p>${d.index===d.lines.length-1&&d.choices?d.choices.map(c=>`<button class="choice" data-action="choice" data-value="${esc(c.id)}"><b>${esc(c.title)}</b><small>${esc(c.desc)}</small></button>`).join(''):`<div class="dialogue-footer"><small>${d.index+1} / ${d.lines.length}</small><button class="primary" data-action="next">${d.index<d.lines.length-1?'Continue':'Back to the basin'} <span>→</span></button></div>`}</section></div>`,'dialogue');}
 next(){const d=this.dialogue;if(!d)return;if(d.index<d.lines.length-1){d.index++;this.renderDialogue();}else if(!d.choices){this.dialogue=null;this.play();d.onComplete?.();}}
 openBook(tab='journal'){this.tab=tab;const g=this.g,s=g.state,chapter=CHAPTERS[questStage(s)];let body='';
  if(tab==='inventory')body=`<div class="eyebrow">Pack light. Make something.</div><h3>Expedition satchel</h3><p>Signature equipment: mechanic’s blade · Wayfarer Loom · ${s.facts.rewarded?'reinforced':'woven'} sailcloth. Field materials are shared with your construction kit.</p><div class="item-grid">${Object.entries(ITEMS).map(([id,item])=>`<article class="item"><div class="item-title"><span>${esc(item.name)}</span><b>${s.inventory[id]}</b></div><p>${esc(item.desc)}</p>${id==='broth'?'<button class="secondary" data-action="heal">Drink broth</button>':''}</article>`).join('')}</div>`;
  if(tab==='journal')body=`<div class="eyebrow">Expedition 01 · ${s.facts.rewarded?'Complete':'In progress'}</div><h3>${chapter.title}</h3><p style="color:var(--gold);margin:18px 0">${chapter.objective}</p><p>${esc(this.bindingText(chapter.detail))}</p><div class="journal-rule"></div><div class="eyebrow">Field observations</div><div class="facts"><span class="fact">${s.discovered.length} / ${LOCATIONS.length} places discovered</span><span class="fact">${s.defeated.length} sentries quieted</span><span class="fact">${s.collected.length} useful caches</span><span class="fact">Water route: ${s.facts.route||'undecided'}</span></div><div class="journal-rule"></div><p>Alternate routes are part of the adventure. The western stepping stones cross the channel; swimming also works while stamina lasts. Essential panels and the intake weight can always be recalled at their local winches.</p><div class="button-row"><button class="secondary" data-action="guide">Loom field guide</button><button class="secondary" data-action="controls">View controls</button></div>`;
  if(tab==='map')body=`<div class="eyebrow">The surface marches</div><h3>Mossglass Basin</h3><p>Click the field map to place a pin. Only discovered places are named. Pins are saved with your expedition.</p><div class="map-area">${this.mapSVG()}</div><div class="map-legend"><span>◇ Discovered place</span><span>▲ Your position</span><span>+ Personal pin</span><span>${s.pins.length} / 12 pins</span></div><div class="button-row"><button class="secondary" data-action="travelCamp">Travel to Reedwake</button>${s.discovered.includes('bellwether')?'<button class="secondary" data-action="travelNorth">Travel to intake beacon</button>':''}<button class="secondary" data-action="clearPins">Clear pins</button></div>`;
  if(tab==='blueprints')body=`<div class="eyebrow">Working arrangements, kept for later</div><h3>Construction fieldbook</h3><p>Record up to 12 components within 18 paces. Blueprints store actual relative positions and rotations. Reconstruction spends the listed materials; dismantling owned parts returns them. Field limit: 24 components.</p><div class="bp-create"><input id="blueprint-name" maxlength="32" aria-label="Blueprint name" placeholder="Name this arrangement"><button class="primary" data-action="saveBlueprint">Record nearby build</button></div>${s.blueprints.map(bp=>`<div class="bp-row"><div><b>${esc(bp.name)}</b><p>${bp.parts.length} parts · ${Object.entries(blueprintCost(bp)).map(([k,v])=>v+' '+k).join(' · ')}</p></div><div><button class="secondary" data-action="buildBlueprint" data-value="${esc(bp.id)}">Reconstruct</button><button class="secondary" data-action="deleteBlueprint" data-value="${esc(bp.id)}">Delete</button></div></div>`).join('')||'<p style="margin-top:28px">No recorded builds yet. Move some parts into an arrangement, then record it here.</p>'}<div class="button-row"><button class="secondary" data-action="dismantle">Dismantle nearest owned part</button></div>`;
  if(tab==='settings')body=renderSettings(this.g);
  if(tab==='pause')body=`<div class="eyebrow">A moment in the wild</div><h3>Expedition paused</h3><p>${chapter.objective}</p><div class="button-row"><button class="primary" data-action="resume">Return to adventure</button><button class="secondary" data-action="save">Save expedition</button><button class="secondary" data-action="load">Load saved expedition</button><button class="secondary" data-action="recover">Recover to safe ground</button></div><div class="button-row"><button class="secondary" data-action="credits">Credits & provenance</button><button class="secondary" data-action="title">Save & title screen</button></div><div class="journal-rule"></div><p>Movement: WASD · mouse to look · Space to jump, then Space in the air for sailcloth · Shift to sprint · E to interact · Q for Threadbind · click or X to attack · Shift + attack for heavy attack · right click to block · C to dodge · H for broth. Arrow keys also turn the camera.</p>`;
  this.set(`<div class="modal-shade"><section class="fieldbook" role="dialog" aria-modal="true" aria-label="Expedition fieldbook"><header class="book-top"><div><div class="eyebrow" style="margin-bottom:7px">Wayfarer’s fieldbook</div><h2>Aetherwild</h2></div><button class="secondary" data-action="resume">${g.started?'Return':'Title screen'} <span style="margin-left:18px">×</span></button></header><nav class="book-tabs">${['journal','inventory','map','blueprints','settings','pause'].map(t=>`<button class="${t===tab?'active':''}" data-action="tab" data-value="${t}">${t==='inventory'?'Satchel':t}</button>`).join('')}</nav><div class="book-body">${body}</div><footer class="book-footer"><span>${s.saveTime?'Saved '+new Date(s.saveTime).toLocaleTimeString():'Autosave at safe ground'} · Browser-local save</span><span>EXPEDITION ${Math.floor(s.playtime/60)} min · v0.3</span></footer></section></div>`,'menu');}
 settingsHTML(){const s=this.g.settings;const slider=(k,n,min,max,step)=>`<label class="setting">${n}<input type="range" min="${min}" max="${max}" step="${step}" value="${s[k]}" data-setting="${k}" aria-label="${n}"></label>`;const toggle=(k,n)=>`<label class="setting">${n}<input type="checkbox" ${s[k]?'checked':''} data-setting="${k}"></label>`;return `<div class="eyebrow">Make the expedition yours</div><h3>Settings & accessibility</h3><div class="settings-grid">${slider('music','Music',0,1,.05)}${slider('sfx','Effects',0,1,.05)}${slider('ambient','Wind & ambience',0,1,.05)}${slider('sensitivity','Mouse sensitivity',.2,2.5,.1)}${slider('gamepadSensitivity','Gamepad sensitivity',.2,2.5,.1)}${slider('textScale','Text size',.85,1.35,.05)}${toggle('invertY','Invert camera Y')}${toggle('reducedMotion','Reduced motion')}${toggle('highContrast','High contrast HUD')}${toggle('subtitles','Essential sound captions')}${toggle('climbAssist','Mineral climbing assistance')}${toggle('sprintToggle','Toggle sprint')}<label class="setting">Render quality<select data-setting="quality"><option value="high" ${s.quality==='high'?'selected':''}>High</option><option value="low" ${s.quality==='low'?'selected':''}>Performance</option></select></label></div><div class="journal-rule"></div><div class="eyebrow">Remap controls · select a key, then press a replacement</div><div class="control-grid">${Object.entries(ACTION_LABELS).map(([a,n])=>`<div class="control"><span>${n}</span><button data-action="rebind" data-value="${a}">${keyName(s.bindings[a])}</button></div>`).join('')}</div><div class="button-row"><button class="secondary" data-action="resetControls">Reset controls</button></div>`;}
 mapSVG(){const g=this.g;return `<svg class="worldmap" viewBox="-170 -160 340 320" preserveAspectRatio="xMidYMid meet" role="img" aria-label="Mossglass Basin map"><defs><pattern id="grid" width="20" height="20" patternUnits="userSpaceOnUse"><path d="M20 0H0V20" stroke="#e2ddad" stroke-width=".2" fill="none"/></pattern></defs><rect x="-170" y="-160" width="340" height="320" fill="#7c9169"/><path d="M-160-140Q-90-90-140-20T-150 150M140-160Q100-90 155-10T130 160" fill="none" stroke="#aab088" stroke-width="25"/><path d="M-170 46Q-80 30 0 42T170 39" fill="none" stroke="#69a99b" stroke-width="18"/><ellipse cx="68" cy="35" rx="44" ry="41" fill="#69a99b"/><path d="M0 109L-28 60V27L-16-20L0-103M-28 60L-75 55L-98 3M-16-20L76-44M0 89L83 40" stroke="#d1c593" stroke-width="2" fill="none" stroke-dasharray="2 1"/><rect x="-170" y="-160" width="340" height="320" fill="url(#grid)"/>${LOCATIONS.filter(l=>g.state.discovered.includes(l.id)).map(l=>`<g transform="translate(${l.x},${l.z})"><path d="M0-4 4 0 0 4-4 0Z" fill="#f0df9e" stroke="#4b6c50" stroke-width="1"/><text x="0" y="-8" text-anchor="middle" fill="#f9f0cf" stroke="#476948" stroke-width=".5" paint-order="stroke" font-family="sans-serif" font-size="5">${esc(l.name)}</text></g>`).join('')}${g.state.pins.map(p=>`<path d="M${p.x-3} ${p.z}h6m-3-3v6" stroke="#f1bd87" stroke-width="1.1"/>`).join('')}<g transform="translate(${g.player.pos.x},${g.player.pos.z}) rotate(${-g.player.yaw*180/Math.PI})"><path d="M0-5 3 4 0 2-3 4Z" fill="#fff2c6" stroke="#284f3e" stroke-width=".8"/></g><text x="148" y="-140" font-family="serif" font-size="8" fill="#ede6be">N ↑</text></svg>`;}
 mapPin(e){const svg=e.target.closest('svg');if(!svg||this.g.state.pins.length>=12)return;const pt=svg.createSVGPoint();pt.x=e.clientX;pt.y=e.clientY;const p=pt.matrixTransform(svg.getScreenCTM().inverse());if(Math.abs(p.x)<170&&Math.abs(p.y)<160){this.g.state.pins.push({x:p.x,z:p.y,note:'Field pin'});this.openBook('map');}}
 ending(){this.set(`<div class="modal-shade"><section class="ending"><div class="eyebrow">Chapter I · complete</div><div class="title-art" style="margin:25px auto 0">${LOGO}</div><h2>A signal beyond the clouds</h2><p>“Iri. I’m alive. Find the Ninth Relay.”</p><p style="margin-top:18px">${this.g.state.facts.route==='roots'?'The hollow drinks again. Beneath its light, an old conduit hums toward the Crown. Sella unfolds a sky chart.':'Water returns to the old road. The expedition can bring its supplies through. Sella unfolds a sky chart.'} Eda crossed alive. Now you have a place to look.</p><p style="color:var(--gold);margin-top:20px">Reinforced sailcloth · +30 stamina · Camp travel</p><div class="button-row"><button class="primary" data-action="resume">Explore the basin ↗</button><button class="secondary" data-action="tab" data-value="journal">Open fieldbook</button></div><p style="font-size:.65rem;margin-top:24px;color:var(--dim)">The Ninth Relay continues the planned adventure. This playable chapter ends here.</p></section></div>`,'ending');}
 death(){this.set(`<div class="modal-shade"><section class="ending death"><div class="eyebrow">The wild keeps going</div><h2>A thread, unbroken.</h2><p>Your expedition and discoveries are safe.<br>Catch your breath at your last safe footing.</p><div class="button-row"><button class="primary" data-action="retry">Try again ↗</button><button class="secondary" data-action="load">Load saved expedition</button></div></section></div>`,'death');}
 saveSlots(mode='load'){
  const slots=this.g.slots.list();
  this.set(`<div class="modal-shade"><section class="fieldbook" role="dialog" aria-modal="true" aria-label="Expedition save slots"><header class="book-top"><div><div class="eyebrow">Your journeys, kept separately</div><h2>${mode==='new'?'New expedition':'Load expedition'}</h2></div><button class="secondary" data-action="resume">Back ×</button></header><div class="book-body">${mode==='new'?'<label class="setting">Expedition name<input id="expedition-name" maxlength="32" value="New Expedition" aria-label="Expedition name"></label><p>Choose an empty slot. Existing expeditions are preserved.</p>':'<p>Every slot has a verified save and a previous backup. Your original expedition remains in slot 1.</p>'}<div class="save-slot-grid">${slots.map(s=>`<article class="save-slot"><div class="eyebrow">SLOT ${s.id}</div><h3>${s.occupied?esc(s.name):'Empty slot'}</h3><p>${s.state?Math.floor(s.state.playtime/60)+' minutes · '+(s.state.saveTime?new Date(s.state.saveTime).toLocaleString():'Not yet saved'):s.occupied?'The primary save is unreadable. Its data has been preserved.':'Ready for a new journey.'}</p>${s.error?'<p style="color:var(--gold)">'+esc(s.error)+'</p>':''}${mode==='new'&&!s.occupied?`<button class="primary" data-action="createExpedition" data-value="${s.id}">Begin here ↗</button>`:s.state?`<button class="secondary" data-action="loadSlot" data-value="${s.id}">Load ${esc(s.name)}</button>`:'<span class="muted">'+(s.occupied?'Preserved for recovery':'No expedition yet')+'</span>'}</article>`).join('')}</div><div class="button-row"><button class="secondary" data-action="abilityWheel">Abilities</button></div></div><footer class="book-footer">Browser-local slots · New games never replace an occupied slot</footer></section></div>`,'menu');
 }
 confirmLoad(id){const s=this.g.slots.list().find(v=>v.id===id);if(!s?.state)return;this.set(`<div class="modal-shade"><section class="dialogue"><div class="eyebrow">Change expeditions</div><h2>Load ${esc(s.name)}?</h2><p>Your current expedition will be saved first. Loading changes the active slot and returns you to this expedition’s saved position.</p><div class="button-row"><button class="primary" data-action="confirmLoad" data-value="${id}">Save current & load</button><button class="secondary" data-action="resume">Stay here</button></div></section></div>`,'menu');}
 abilityWheel(){this.g.rise.cancel();this.g.releaseHeld(false);this.set(`<div class="modal-shade"><section class="ability-wheel" role="dialog" aria-modal="true" aria-label="Wayfarer Loom abilities"><div class="eyebrow">Wayfarer Loom · choose a thread</div><h2>The brace remembers</h2><div class="ability-choices"><button data-action="chooseAbility" data-value="weave"><span class="ability-glyph">⌘</span><strong>Threadbind</strong><small>Weave marked objects into working routes.</small><em>24-pace reach · rigid sockets · undo</em><b>[${this.g.input.label('weave')}]</b></button><button data-action="chooseAbility" data-value="rise"><span class="ability-glyph">⇡</span><strong>Rise</strong><small>Travel through a marked ceramic canopy.</small><em>16-pace ascent · clear exit · 10 stamina</em><b>[${this.g.input.label('rise')}]</b></button></div><p>Only available abilities are shown. Cancel safely with ${this.g.input.label('pause')}.</p><button class="secondary" data-action="resume">Return to the basin</button></section></div>`,'abilityWheel');}
 action(a,value){const g=this.g;
  if(a==='new'){this.saveSlots('new');return;}if(a==='load'){this.saveSlots('load');return;}if(a==='continue'){g.loadGame();return;}
  if(a==='createExpedition'){g.newGame(document.querySelector('#expedition-name')?.value,value);return;}
  if(a==='loadSlot'){if(g.started)this.confirmLoad(value);else g.loadGame(value);return;}
  if(a==='confirmLoad'){if(g.save(false))g.loadGame(value);return;}
  if(a==='abilityWheel'){this.abilityWheel();return;}
  if(a==='chooseAbility'){this.play();g.rise.cancel();g.loom=false;g.activeAbility=value;if(value==='rise')g.rise.toggle();else g.loom=true;return;}
  if(a==='new')g.newGame();if(a==='continue'||a==='load')g.loadGame();if(a==='resume'){if(g.started)this.play();else this.title();}if(a==='settings')this.openBook('settings');if(a==='tab')this.openBook(value);if(a==='next')this.next();if(a==='choice'){const d=this.dialogue;this.dialogue=null;this.play();d.onComplete?.(value);}if(a==='save'){g.save(true);this.openBook(this.tab);}if(a==='title'){g.save(false);g.started=false;this.title();}if(a==='retry'){g.respawn(true);this.play();}if(a==='recover'){g.respawn(false);this.play();}if(a==='heal'){g.heal();this.openBook('inventory');}if(a==='guide')g.guide();if(a==='controls')this.openBook('settings');if(a==='travelCamp')g.travel('reedwake');if(a==='travelNorth')g.travel('bellwether');if(a==='clearPins'){g.state.pins=[];this.openBook('map');}if(a==='saveBlueprint')g.recordBlueprint(document.querySelector('#blueprint-name')?.value||'Field arrangement');if(a==='buildBlueprint')g.buildBlueprint(value);if(a==='deleteBlueprint'){g.state.blueprints=g.state.blueprints.filter(b=>b.id!==value);this.openBook('blueprints');}if(a==='dismantle')g.dismantle();if(a==='rebind'){this.toast('Press a replacement key or mouse button.');g.input.rebind=code=>{const prior=g.settings.bindings[value];for(const[k,v]of Object.entries(g.settings.bindings))if(v===code)g.settings.bindings[k]=prior;g.settings.bindings[value]=code;g.applySettings();this.openBook('settings');};}if(a==='resetControls'){g.settings.bindings={...DEFAULT_SETTINGS.bindings};g.applySettings();this.openBook('settings');}if(a==='credits'){this.set(`<div class="modal-shade"><section class="dialogue"><div class="eyebrow">Made for this strange little world</div><h2>Aetherwild</h2><p class="credits">Original world, writing, procedural art, animation, interface and synthesized music created for this game. Three.js r160 · MIT license.<br><br>This is an early prototype of Mossglass Basin. No borrowed franchise assets, maps, characters or music. See ASSETS.md and BUILD_STATUS.md in the project for provenance and verification.</p><div class="button-row"><button class="primary" data-action="tab" data-value="pause">Back to fieldbook</button></div></section></div>`,'menu');}}
}
